perspectives.style:
/* Each property here is one that Kumu's property reference gives the selector's type (element,
   connection or loop: its table marks which type takes which property); check a new one there
   before writing it, and see it work in a test import. */

@controls {
  bottom-left {
    text {
      value: "**Tint** = SETS domain: green = Ecological, blue = Social, orange = Technological<br>**Boxes:** square corners = stock, rounded corners = auxiliary, italic label = constant (exogenous), thick border = adaptive practice<br>**Links:** blue = + (same direction), red = − (opposite direction), two strokes across = delay";
    }
  }
}

@settings {
  layout: static;
  theme: light;
  background-color: #FFFFFF;
  culling: off;
}

/* ---------- Elements: the page's look, values from draw_cld.py ---------- */
/* each box's fill (its SETS domain's tint, draw_cld.py's TINT), width and height are rules
   build.py generates below this view in docs/kumu/kumu-project.json. Kumu draws text at about 0.6 of
   its font-size in map units, so each font-size is the page's x 1.5, to fill the box
   draw_cld.py fits */
/* pill: Kumu's rectangle with rounded corners */
element {
  shape: pill;
  border-color: #444444;
  border-width: 1.5;
  font-size: 42;
  font-weight: normal;
  font-color: #000000;
  text-align: center;
  /* build.py puts a double space where the page breaks a label's line */
  text-overflow: manual;
  shadow-visibility: hidden;
}

["element type"="stock"] {
  shape: rectangle;
}

/* Kumu has no dashed border: a constant gets an italic label */
["element type"="constant"] {
  font-style: italic;
}

["adaptive practice"="yes"] {
  border-width: 5;
}

/* ---------- Regions: the page's two subsystem regions as a background image ---------- */
/* the rule of Kumu's images guide (docs.kumu.io/guides/images.html); build.py adds the element,
   pinned at the centre of the regions' frame, and its width and height, the frame's, and puts the
   regions in place of IMAGE, as a data URL of the SVG it draws, so the image travels inside the
   project file */
#background {
  image-url: url(data:image/svg+xml;base64,);
  layer: background;
  shape: rectangle;
  color: transparent;
  image-size: contain;
  image-resolution: original;
  label-visibility: none;
  border-width: 0;
}

/* ---------- Links: one width, the sign's colour ---------- */
/* (no global curvature: each link keeps its own curve from the map) */
connection {
  size: 2.5;
  style: solid;
  arrow-visibility: visible;
  label: none;
  font-size: 63;
  font-weight: bold;
}

["polarity"="positive"] {
  color: #2166AC;
  font-color: #2166AC;
}

["polarity"="negative"] {
  color: #B2182B;
  font-color: #B2182B;
}

/* ---------- Loops: Kumu's named loops, no label on the map ---------- */
/* the full drawing has no loop marks (the layout decision in `cld-drawing.md`); Kumu's property reference
   gives loops `label`, not `label-visibility`. The loop maps' view is this view without this
   section (build.py), so each loop's label shows at its mark */
loop {
  label: none;
}

