/* The Kumu view of the Actor Map inside docs/kumu/kumu-project.json, as cld-view.scss is the CLD's. Each
   property here is one cld-view.scss already uses; check a new one in Kumu's property reference before
   writing it, and see it work in a test import. build.py adds below it each relation kind's colour
   and dash (draw_actor_map.py's KIND), each box's size and the bands' size. */

@controls {
  bottom-left {
    text {
      value: "**Bands** = level: Global, International, National, Local / Provincial / Regional<br>**Links** = relation, read from the actor at the tail: authority over (dark), finances (orange), buys from (orange, dashed), advises (violet, dashed), represents (violet), works with (green, dashed)";
    }
  }
}

@settings {
  layout: static;
  theme: light;
  background-color: #FFFFFF;
  culling: off;
}

