  border-color: #444444;
  border-width: 2;
  font-size: 42;
  font-weight: normal;
  font-color: #000000;
  text-align: center;
  /* build.py puts a double space where the page breaks a label's line */
  text-overflow: manual;
  shadow-visibility: hidden;
}

/* ---------- Bands: the page's level bands as a background image ---------- */
/* as cld-view.scss's #background: build.py adds the element, pinned at the centre of the bands'
